namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – DataRow (compile-time constants)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price, any quantity")]
    [DataRow(99.99, 0, 0.20, 0.00, DisplayName = "Zero quantity yields zero")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} but got {result}");
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – DynamicData (complex/edge cases)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalEdgeCases
    {
        get
        {
            yield return new object[] { 0.01m, 1, 0.0m, 0.01m, "Minimum meaningful price" };
            yield return new object[] { 9999.99m, 100, 1.0m, 1_999_998.00m, "Large order, max tax" };
            yield return new object[] { 5.00m, 1, 0.0725m, 5.3625m, "Fractional tax rate" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases), DynamicDataSourceType.Property)]
    public void CalculateTotal_EdgeCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result, $"Scenario: {scenario}");
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – invalid inputs throw
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax > 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% off")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off (free)")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DynamicData from method
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> GetDiscountBoundaryData()
    {
        yield return new object[] { 200.00m, 0.01m, 199.98m, "Minimal discount" };
        yield return new object[] { 200.00m, 99.99m, 0.02m, "Near-total discount" };
        yield return new object[] { 0.00m, 50.0m, 0.00m, "Zero price unaffected" };
    }

    [TestMethod]
    [DynamicData(nameof(GetDiscountBoundaryData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_BoundaryCases_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Scenario: {scenario}");
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, -1.0, DisplayName = "Negative discount throws")]
    [DataRow(100.00, 100.01, DisplayName = "Discount > 100 throws")]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRange(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

